import sysimport unittestfrom pathlib import Pathsys.path.insert(0,str(Path(__file__).resolve().parents[1]/'scripts'))import configure_thinltoclass ThinLTOTests(unittest.TestCase):    def test_redirect_existing_cache(self):        source='ifdef CONFIG_LTO_CLANG_THIN\nKBUILD_LDFLAGS += --thinlto-cache-dir=$(extmod-prefix).thinlto-cache\nendif\n'        result=configure_thinlto.configure(source,'/cache/lto')        self.assertIn('--thinlto-cache-dir=/cache/lto',result)        self.assertNotIn('$(extmod-prefix).thinlto-cache',result)    def test_add_cache_only_in_thin_lto_condition(self):        source='ifdef CONFIG_LTO_CLANG\nifdef CONFIG_LTO_CLANG_THIN\nCC_FLAGS_LTO := -flto=thin\nendif\nendif\n'        result=configure_thinlto.configure(source,'/cache/lto')        self.assertIn('ifdef CONFIG_LTO_CLANG_THIN\nKBUILD_LDFLAGS += --thinlto-cache-dir=/cache/lto\n',result)        self.assertIn('CC_FLAGS_LTO := -flto=thin',result)    def test_unrecognized_source_is_unchanged(self):        self.assertEqual(configure_thinlto.configure('KBUILD_LDFLAGS :=\n','/cache/lto'),'KBUILD_LDFLAGS :=\n')    def test_configure_twice_is_idempotent(self):        source='ifdef CONFIG_LTO_CLANG_THIN\nendif\n'        once=configure_thinlto.configure(source,'/cache/lto')        self.assertIn('--thinlto-cache-dir=',once)        self.assertEqual(once,configure_thinlto.configure(once,'/cache/lto'))